def check(ctx):
    if ctx.held_object() != "u_brown":
        return None
    j = ctx.joint("finger_joint")
    if j is None or j["effort"] is None:
        return None
    e = abs(j["effort"])
    thr = ctx.value("max_clamp_effort")
    if e > thr:
        return {"value": e, "detail": "finger_joint effort " + str(e) + " exceeded max_clamp_effort while holding u_brown"}
    return None

def check(ctx):
    if ctx.held_object() != "u_brown":
        ctx.state["rel0"] = None
        return None
    rel = ctx.transform("tcp", "u_brown")
    if "rel0" not in ctx.state or ctx.state["rel0"] is None:
        ctx.state["rel0"] = rel["translation"]
        return None
    d = ctx.dist(ctx.state["rel0"], rel["translation"])
    thr = ctx.value("grasp_slip_tolerance_m")
    if d > thr:
        return {"value": d, "detail": "u_brown shifted " + str(d) + "m relative to gripper"}
    return None

